INSERT INTO card_translations (card_id, locale, payload) VALUES ('fool', 'vi', '{"name":"Kẻ Khờ","meaning":"Một trang giấy trắng và bước nhảy của niềm tin — hành trình mới bắt đầu với trái tim rộng mở.","advice":"Tin vào con đường phía trước và thực hiện bước đầu tiên, dù bạn chưa có mọi câu trả lời.","yesNoMeaning":"Khởi đầu mới hiếm khi có câu trả lời cố định — kết quả phụ thuộc vào bước đi của bạn."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('magician', 'vi', '{"name":"Nhà Ảo Thuật","meaning":"Bạn đã có đủ công cụ cần thiết. Tập trung ý chí và biến ý định thành hành động.","advice":"Chủ động sử dụng kỹ năng và nguồn lực — đây là lúc biến ý tưởng thành hiện thực.","yesNoMeaning":"Bạn đã có những gì cần thiết — năng lượng ủng hộ việc tiến lên có trọng tâm."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('high-priestess', 'vi', '{"name":"Nữ Tư Tế","meaning":"Trí tuệ thầm lặng ẩn dưới bề mặt. Hãy lắng nghe trực giác và tiếng nói bên trong.","advice":"Tạm dừng, hướng vào bên trong và để trực giác dẫn đường trước khi hành động.","yesNoMeaning":"Câu trả lời còn ẩn sâu — hãy tin vào trực giác thay vì ép mình phải chọn có hay không."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('empress', 'vi', '{"name":"Hoàng Hậu","meaning":"Sự phát triển, đủ đầy và năng lượng nuôi dưỡng bao quanh bạn. Hãy để vẻ đẹp và sự quan tâm nở rộ.","advice":"Kiên nhẫn và rộng lượng — sáng tạo bằng tình yêu và để mọi thứ chín muồi tự nhiên.","yesNoMeaning":"Sự phát triển, đủ đầy và chăm sóc nâng đỡ mong muốn của bạn — một lời có nhẹ nhàng."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('emperor', 'vi', '{"name":"Hoàng Đế","meaning":"Kỷ cương, uy quyền và khả năng dẫn dắt vững vàng. Hãy xây dựng trên nền tảng chắc chắn bằng sự kỷ luật.","advice":"Chủ động với kế hoạch rõ ràng. Ranh giới vững chắc mang lại sự ổn định lâu dài.","yesNoMeaning":"Kỷ cương, uy quyền và kỷ luật bền bỉ đứng sau một lời có tự tin."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('hierophant', 'vi', '{"name":"Giáo Hoàng","meaning":"Truyền thống và lời hướng dẫn đáng tin mang đến con đường vững vàng. Hãy học từ những điều đã có trước.","advice":"Tiếp thu kinh nghiệm đã được kiểm chứng và tìm lời khuyên từ người bạn tin tưởng.","yesNoMeaning":"Truyền thống và sự hướng dẫn đáng tin nghiêng về có — hãy dựa vào những gì đã chứng minh giá trị."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('lovers', 'vi', '{"name":"Đôi Tình Nhân","meaning":"Một mối gắn kết ý nghĩa hoặc lựa chọn quan trọng. Hãy đi theo điều trái tim thật sự trân trọng.","advice":"Lựa chọn chân thành và đúng với giá trị của mình — sự kết nối sâu sắc hơn khi bạn thành thật.","yesNoMeaning":"Trái tim và giá trị của bạn đang đồng điệu — câu trả lời là có, nhất là khi bạn lựa chọn chân thành."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('chariot', 'vi', '{"name":"Cỗ Xe","meaning":"Ý chí và đà tiến đưa bạn về phía trước. Giữ sự tập trung để vượt qua thử thách.","advice":"Hướng mắt về mục tiêu và tự tin điều khiển hành trình qua từng trở ngại.","yesNoMeaning":"Ý chí và đà tiến đứng về phía bạn — nghiêng về có, nếu bạn giữ cam kết."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('strength', 'vi', '{"name":"Sức Mạnh","meaning":"Sức mạnh thật sự dịu dàng — kiên nhẫn, can đảm và lòng trắc ẩn giúp chế ngự thử thách.","advice":"Dẫn dắt bằng sức mạnh điềm tĩnh. Bàn tay mềm mại thường là bàn tay mạnh mẽ nhất.","yesNoMeaning":"Can đảm dịu dàng và quyết tâm bền bỉ nghiêng về có — hãy bình tĩnh, đừng cưỡng ép."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('hermit', 'vi', '{"name":"Ẩn Sĩ","meaning":"Đã đến lúc lùi lại để tìm sự sáng rõ bên trong. Khoảng lặng mang đến câu trả lời sâu sắc hơn.","advice":"Hướng vào bên trong, suy ngẫm và để sự tĩnh lặng chỉ ra điều bạn thật sự cần.","yesNoMeaning":"Chưa phải lúc — lá bài mời bạn lùi lại và hiểu rõ mình trước khi hành động."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('wheel-of-fortune', 'vi', '{"name":"Bánh Xe Số Phận","meaning":"Vận may xoay chuyển và chu kỳ đổi thay. Biến động lúc này là một phần của nhịp điệu lớn hơn.","advice":"Linh hoạt theo dòng chảy — đón nhận bước ngoặt, dù thuận lợi hay không.","yesNoMeaning":"Vận mệnh đang chuyển động — kết quả phụ thuộc vào cách bạn thích nghi, không phải một lời có hay không cố định."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('justice', 'vi', '{"name":"Công Lý","meaning":"Sự thật và công bằng lên tiếng. Nguyên nhân và kết quả đang trở về trạng thái cân bằng.","advice":"Hành động trung thực và cân nhắc cả hai phía để cán cân được công bằng.","yesNoMeaning":"Cán cân vẫn đang cân nhắc — câu trả lời công bằng phụ thuộc vào sự thật và tính trung thực của bạn."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('hanged-man', 'vi', '{"name":"Người Treo Ngược","meaning":"Một khoảng dừng cần thiết. Buông nhu cầu kiểm soát và nhìn tình huống từ góc độ mới.","advice":"Ngừng thúc ép — đón nhận hiện tại và để một cách nhìn mới xuất hiện.","yesNoMeaning":"Cần tạm dừng trước — cưỡng ép lúc này chỉ khiến câu trả lời sáng rõ đến chậm hơn."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('death', 'vi', '{"name":"Cái Chết","meaning":"Một sự kết thúc dọn đường cho tái sinh. Hãy buông điều đã hoàn thành vai trò của nó.","advice":"Buông bỏ không tiếc nuối. Sự chuyển hóa sâu sắc đang mở ra một cánh cửa mới.","yesNoMeaning":"Một kết thúc đang dọn đường — lối đi hiện tại khép lại để lối đi mới bắt đầu."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('temperance', 'vi', '{"name":"Tiết Độ","meaning":"Cân bằng và kiên nhẫn mang lại hòa hợp. Kết hợp những điều đối lập một cách nhẹ nhàng.","advice":"Hành động điều độ và giữ bình tĩnh — từng bước vững vàng sẽ đưa bạn tới đích.","yesNoMeaning":"Cân bằng và kiên nhẫn mang đến hòa hợp — một lời có chừng mực, tiến từng bước vững chắc."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('devil', 'vi', '{"name":"Ác Quỷ","meaning":"Cẩn trọng với sự lệ thuộc, cám dỗ hoặc khuôn mẫu trói buộc. Nhận diện những sợi dây đang giữ bạn.","advice":"Gọi tên điều níu giữ và tìm lại tự do — nhận ra ràng buộc là bước đầu để tháo gỡ.","yesNoMeaning":"Sự lệ thuộc hoặc khuôn mẫu trói buộc đang cản đường — chưa phải lúc, cho đến khi bạn nhận diện và tháo gỡ nó."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('tower', 'vi', '{"name":"Tòa Tháp","meaning":"Biến động bất ngờ phá vỡ điều giả tạo và phơi bày sự thật. Những gì sụp đổ vốn thiếu nền tảng vững chắc.","advice":"Đón nhận xáo trộn — từ đổ vỡ, bạn có thể xây dựng nền tảng sáng rõ hơn.","yesNoMeaning":"Biến động đang phá vỡ cái cũ — cần ổn định lại nền móng trước khi có thể tiến tới một lời có vững vàng."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('star', 'vi', '{"name":"Ngôi Sao","meaning":"Hy vọng, sự chữa lành và cảm hứng lặng lẽ làm mới tinh thần sau giông bão.","advice":"Tin vào ánh sáng phía trước và tiếp tục giữ niềm tin — mong ước của bạn ở trong tầm với.","yesNoMeaning":"Hy vọng và sự hồi phục nhẹ nhàng nghiêng về có — tin vào ánh sáng phía trước và nuôi dưỡng mong ước."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('moon', 'vi', '{"name":"Mặt Trăng","meaning":"Ảo ảnh và sự bất định làm mờ lối đi. Hãy lắng nghe trực giác thay vì chỉ nhìn vẻ ngoài.","advice":"Chậm lại và nhìn sâu hơn. Sự sáng rõ sẽ đến khi màn sương tan đi.","yesNoMeaning":"Ảo ảnh và bất định đang che khuất lối đi — câu trả lời chưa rõ cho đến khi bạn nhìn sâu hơn vẻ ngoài."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('sun', 'vi', '{"name":"Mặt Trời","meaning":"Niềm vui, thành công và sự sáng rõ rạng rỡ. Mọi thứ tràn đầy ánh sáng và sức sống.","advice":"Ăn mừng và tỏa sáng — năng lượng tích cực giúp bạn hướng tới kết quả mong muốn.","yesNoMeaning":"Niềm vui và sự sáng rõ nghiêng mạnh về có — năng lượng đang thuận lợi cho bạn."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('judgement', 'vi', '{"name":"Phán Xét","meaning":"Lời mời vươn lên, đổi mới và thành thật với chính mình. Một thời khắc thức tỉnh.","advice":"Can đảm đáp lại lời mời. Tha thứ cho quá khứ và bước vào chương tiếp theo.","yesNoMeaning":"Lời mời vươn lên và đổi mới nghiêng về có — nhất là khi bạn tha thứ cho quá khứ và đáp lại một cách chân thành."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('world', 'vi', '{"name":"Thế Giới","meaning":"Hoàn thành và viên mãn — một chu kỳ khép lại trong sự trọn vẹn.","advice":"Trân trọng thành tựu của mình. Cánh cửa tới thế giới rộng lớn hơn đang mở ra.","yesNoMeaning":"Sự hoàn thành và trọn vẹn đánh dấu một lời có viên mãn — chu kỳ khép lại thuận lợi."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-wands', 'vi', '{"name":"Át Gậy","meaning":"Tia cảm hứng mở ra con đường sáng tạo đầy táo bạo.","advice":"Bắt đầu khi năng lượng còn mới và cho ý tưởng một bước đi cụ thể.","yesNoMeaning":"Át Gậy nghiêng về có: bắt đầu khi năng lượng còn mới và cho ý tưởng một bước đi cụ thể."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-wands', 'vi', '{"name":"Hai Gậy","meaning":"Tương lai dần thành hình qua việc lập kế hoạch và chọn hướng đi.","advice":"Nhìn xa hơn điều quen thuộc, rồi cam kết với con đường còn chỗ để phát triển.","yesNoMeaning":"Hai Gậy còn tùy điều kiện: nhìn xa hơn điều quen thuộc, rồi cam kết với con đường còn chỗ để phát triển."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-wands', 'vi', '{"name":"Ba Gậy","meaning":"Nỗ lực ban đầu mở rộng khi cơ hội và chân trời mới xuất hiện.","advice":"Tiếp tục xây dựng và sẵn sàng đón nhận phản hồi mà công việc mang lại.","yesNoMeaning":"Ba Gậy nghiêng về có: tiếp tục xây dựng và sẵn sàng đón nhận phản hồi mà công việc mang lại."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-wands', 'vi', '{"name":"Bốn Gậy","meaning":"Sự ổn định, chào đón và niềm vui chung tạo nên nền tảng vững chắc.","advice":"Ghi nhận cột mốc và chia sẻ niềm vui với những người luôn hỗ trợ bạn.","yesNoMeaning":"Bốn Gậy nghiêng về có: ghi nhận cột mốc và chia sẻ niềm vui với những người luôn hỗ trợ bạn."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-wands', 'vi', '{"name":"Năm Gậy","meaning":"Những mục tiêu cạnh tranh gây va chạm, ồn ào hoặc thử thách sự tự tin.","advice":"Biến cạnh tranh thành cơ hội rèn luyện và từ chối xung đột vô nghĩa.","yesNoMeaning":"Năm Gậy còn tùy điều kiện: biến cạnh tranh thành cơ hội rèn luyện và từ chối xung đột vô nghĩa."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-wands', 'vi', '{"name":"Sáu Gậy","meaning":"Sự ghi nhận đến sau nỗ lực bền bỉ và tiến bộ rõ ràng.","advice":"Đón nhận sự khích lệ, nhưng giữ sự tự tin gắn với công việc chân chính.","yesNoMeaning":"Sáu Gậy nghiêng về có: đón nhận sự khích lệ, nhưng giữ sự tự tin gắn với công việc chân chính."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-wands', 'vi', '{"name":"Bảy Gậy","meaning":"Bạn đang giữ vị trí có giá trị trong khi áp lực thử thách quyết tâm.","advice":"Bảo vệ điều quan trọng bằng ranh giới rõ ràng thay vì đối đầu với mọi thách thức.","yesNoMeaning":"Bảy Gậy nghiêng về có: bảo vệ điều quan trọng bằng ranh giới rõ ràng thay vì đối đầu với mọi thách thức."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-wands', 'vi', '{"name":"Tám Gậy","meaning":"Sự việc tăng tốc, tin tức đến và đà tiến xóa tan trì hoãn.","advice":"Hành động kịp thời và giao tiếp thẳng thắn khi con đường đang rộng mở.","yesNoMeaning":"Tám Gậy nghiêng về có: hành động kịp thời và giao tiếp thẳng thắn khi con đường đang rộng mở."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-wands', 'vi', '{"name":"Chín Gậy","meaning":"Sức bền vẫn mạnh mẽ, dù căng thẳng trong quá khứ khiến bạn đề phòng.","advice":"Bảo vệ năng lượng và bước tiếp mà không cho rằng mọi tổn thương sẽ lặp lại.","yesNoMeaning":"Chín Gậy còn tùy điều kiện: bảo vệ năng lượng và bước tiếp mà không cho rằng mọi tổn thương sẽ lặp lại."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-wands', 'vi', '{"name":"Mười Gậy","meaning":"Trách nhiệm trở nên nặng nề và thành công giờ mang theo gánh nặng.","advice":"Chia sẻ công việc, đơn giản hóa và đặt xuống những việc không còn thực sự thuộc về bạn.","yesNoMeaning":"Mười Gậy nghiêng về không: chia sẻ công việc, đơn giản hóa và đặt xuống những việc không còn thực sự thuộc về bạn."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-wands', 'vi', '{"name":"Tiểu Đồng Gậy","meaning":"Sự tò mò mang đến tin tức sôi nổi, thử nghiệm hoặc mối quan tâm sáng tạo mới.","advice":"Can đảm khám phá và để tinh thần người mới giúp bạn học qua hành động.","yesNoMeaning":"Tiểu Đồng Gậy nghiêng về có: can đảm khám phá và để tinh thần người mới giúp bạn học qua hành động."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-wands', 'vi', '{"name":"Kỵ Sĩ Gậy","meaning":"Đam mê lao nhanh về phía trước, mang theo phiêu lưu và cả sự nôn nóng.","advice":"Tận dụng đà tiến, nhưng chọn hướng đi trước khi tốc độ làm phân tán nỗ lực.","yesNoMeaning":"Kỵ Sĩ Gậy còn tùy điều kiện: tận dụng đà tiến, nhưng chọn hướng đi trước khi tốc độ làm phân tán nỗ lực."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-wands', 'vi', '{"name":"Nữ Hoàng Gậy","meaning":"Sự tự tin ấm áp và tinh thần sáng tạo độc lập thu hút người khác đến với tầm nhìn của bạn.","advice":"Tin vào sức hiện diện của mình, khích lệ người khác và đừng thu nhỏ hoài bão.","yesNoMeaning":"Nữ Hoàng Gậy nghiêng về có: tin vào sức hiện diện của mình, khích lệ người khác và đừng thu nhỏ hoài bão."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-wands', 'vi', '{"name":"Vua Gậy","meaning":"Tầm nhìn chín chắn biến cảm hứng thành khả năng lãnh đạo quyết đoán và có đạo đức.","advice":"Dẫn dắt từ mục đích lớn hơn và tạo không gian để người khác đóng góp.","yesNoMeaning":"Vua Gậy nghiêng về có: dẫn dắt từ mục đích lớn hơn và tạo không gian để người khác đóng góp."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-cups', 'vi', '{"name":"Át Cốc","meaning":"Trái tim mở ra với tình cảm mới, lòng trắc ẩn và sự hồi sinh cảm xúc.","advice":"Đón nhận cảm xúc chân thành và để sự quan tâm tuôn chảy mà không ép buộc kết quả.","yesNoMeaning":"Át Cốc nghiêng về có: đón nhận cảm xúc chân thành và để sự quan tâm tuôn chảy mà không ép buộc kết quả."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-cups', 'vi', '{"name":"Hai Cốc","meaning":"Sự thấu hiểu hai chiều tạo nên quan hệ đồng hành, sức hút hoặc đồng thuận chân thành.","advice":"Gặp người kia ở vị thế bình đẳng và nói từ trái tim.","yesNoMeaning":"Hai Cốc nghiêng về có: gặp người kia ở vị thế bình đẳng và nói từ trái tim."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-cups', 'vi', '{"name":"Ba Cốc","meaning":"Tình bạn, cộng đồng và niềm vui sẻ chia mang đến chỗ dựa tinh thần.","advice":"Cùng nhau ăn mừng và ghi nhớ ai thực sự có mặt khi bạn cần.","yesNoMeaning":"Ba Cốc nghiêng về có: cùng nhau ăn mừng và ghi nhớ ai thực sự có mặt khi bạn cần."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-cups', 'vi', '{"name":"Bốn Cốc","meaning":"Sự thu mình về cảm xúc khiến bạn khó nhận ra món quà đang được trao.","advice":"Ngừng so sánh và nhìn lại điều đang được lặng lẽ dành cho bạn.","yesNoMeaning":"Bốn Cốc nghiêng về không: ngừng so sánh và nhìn lại điều đang được lặng lẽ dành cho bạn."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-cups', 'vi', '{"name":"Năm Cốc","meaning":"Mất mát khiến bạn chú ý tới điều đã đổ vỡ, trong khi điều ý nghĩa vẫn còn.","advice":"Trân trọng nỗi thất vọng, rồi hướng về sự hỗ trợ vẫn hiện diện.","yesNoMeaning":"Năm Cốc nghiêng về không: trân trọng nỗi thất vọng, rồi hướng về sự hỗ trợ vẫn hiện diện."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-cups', 'vi', '{"name":"Sáu Cốc","meaning":"Ký ức, sự hồn nhiên hoặc mối gắn kết quen thuộc trở lại với hơi ấm dịu dàng.","advice":"Đón nhận sự tử tế của quá khứ mà không cho rằng mình phải sống lại trong đó.","yesNoMeaning":"Sáu Cốc nghiêng về có: đón nhận sự tử tế của quá khứ mà không cho rằng mình phải sống lại trong đó."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-cups', 'vi', '{"name":"Bảy Cốc","meaning":"Nhiều khả năng hấp dẫn làm mờ ranh giới giữa tầm nhìn và ảo tưởng.","advice":"Thu hẹp lựa chọn và đối chiếu một ước mơ với thực tế trước khi cam kết.","yesNoMeaning":"Bảy Cốc chưa rõ câu trả lời: thu hẹp lựa chọn và đối chiếu một ước mơ với thực tế trước khi cam kết."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-cups', 'vi', '{"name":"Tám Cốc","meaning":"Một tình huống từng ý nghĩa nay không còn nuôi dưỡng trái tim.","advice":"Chân thành rời đi và hướng tới sự mãn nguyện sâu sắc hơn mà bạn cần lúc này.","yesNoMeaning":"Tám Cốc nghiêng về không: chân thành rời đi và hướng tới sự mãn nguyện sâu sắc hơn mà bạn cần lúc này."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-cups', 'vi', '{"name":"Chín Cốc","meaning":"Sự hài lòng và biết ơn khiến một mong ước chân thành trở nên gần gũi.","advice":"Tận hưởng hiện tại và tự hỏi mong ước đó có phù hợp với giá trị sâu xa của bạn không.","yesNoMeaning":"Chín Cốc nghiêng về có: tận hưởng hiện tại và tự hỏi mong ước đó có phù hợp với giá trị sâu xa của bạn không."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-cups', 'vi', '{"name":"Mười Cốc","meaning":"Hòa hợp cảm xúc, cảm giác thuộc về và kết nối bền lâu bao quanh mái ấm.","advice":"Nuôi dưỡng những mối gắn kết giúp niềm vui bền vững và được sẻ chia.","yesNoMeaning":"Mười Cốc nghiêng về có: nuôi dưỡng những mối gắn kết giúp niềm vui bền vững và được sẻ chia."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-cups', 'vi', '{"name":"Tiểu Đồng Cốc","meaning":"Một thông điệp dịu dàng hoặc khám phá từ trực giác mời bạn mở lòng.","advice":"Tò mò tìm hiểu cảm xúc và đáp lại chân thành thay vì suy đoán.","yesNoMeaning":"Tiểu Đồng Cốc còn tùy điều kiện: tò mò tìm hiểu cảm xúc và đáp lại chân thành thay vì suy đoán."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-cups', 'vi', '{"name":"Kỵ Sĩ Cốc","meaning":"Sự lãng mạn, trí tưởng tượng hoặc lý tưởng dẫn trái tim về phía trước.","advice":"Đón nhận lời mời, nhưng vẫn thực tế khi những lời hứa dần được thể hiện.","yesNoMeaning":"Kỵ Sĩ Cốc nghiêng về có: đón nhận lời mời, nhưng vẫn thực tế khi những lời hứa dần được thể hiện."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-cups', 'vi', '{"name":"Nữ Hoàng Cốc","meaning":"Sự đồng cảm sâu sắc và trực giác tạo nên không gian bình yên cho sự thật.","advice":"Lắng nghe bằng lòng trắc ẩn, đồng thời giữ ranh giới để sự quan tâm luôn lành mạnh.","yesNoMeaning":"Nữ Hoàng Cốc nghiêng về có: lắng nghe bằng lòng trắc ẩn, đồng thời giữ ranh giới để sự quan tâm luôn lành mạnh."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-cups', 'vi', '{"name":"Vua Cốc","meaning":"Sự trưởng thành cảm xúc giúp ổn định những cảm giác mạnh mà không đè nén chúng.","advice":"Đáp lại bằng lòng trắc ẩn và sự tự chủ, nhất là khi người khác phản ứng mạnh.","yesNoMeaning":"Vua Cốc nghiêng về có: đáp lại bằng lòng trắc ẩn và sự tự chủ, nhất là khi người khác phản ứng mạnh."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-swords', 'vi', '{"name":"Át Kiếm","meaning":"Một nhận thức sáng rõ xuyên qua bối rối và hé lộ sự thật mới.","advice":"Gọi tên vấn đề thẳng thắn và dùng sự sáng rõ để đưa ra quyết định công bằng.","yesNoMeaning":"Át Kiếm nghiêng về có: gọi tên vấn đề thẳng thắn và dùng sự sáng rõ để đưa ra quyết định công bằng."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-swords', 'vi', '{"name":"Hai Kiếm","meaning":"Thế bế tắc đầy phòng thủ trì hoãn một lựa chọn không thể treo mãi.","advice":"Nhẹ nhàng tháo bỏ tấm che mắt, tìm dữ kiện còn thiếu và quyết định trong cân bằng.","yesNoMeaning":"Hai Kiếm chưa rõ câu trả lời: nhẹ nhàng tháo bỏ tấm che mắt, tìm dữ kiện còn thiếu và quyết định trong cân bằng."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-swords', 'vi', '{"name":"Ba Kiếm","meaning":"Một sự thật đau lòng, chia ly hoặc thất vọng cần được thừa nhận.","advice":"Để cảm xúc đi qua và đừng biến tổn thương thành câu chuyện vĩnh viễn về mình.","yesNoMeaning":"Ba Kiếm nghiêng về không: để cảm xúc đi qua và đừng biến tổn thương thành câu chuyện vĩnh viễn về mình."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-swords', 'vi', '{"name":"Bốn Kiếm","meaning":"Bạn cần nghỉ ngơi và tĩnh tâm sau áp lực hoặc xung đột.","advice":"Tạm dừng trước khi trả lời. Hồi phục có giá trị khi giúp suy nghĩ sáng rõ trở lại.","yesNoMeaning":"Bốn Kiếm nghiêng về không: tạm dừng trước khi trả lời. Hồi phục có giá trị khi giúp suy nghĩ sáng rõ trở lại."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-swords', 'vi', '{"name":"Năm Kiếm","meaning":"Xung đột có thể tạo ra chiến thắng rỗng tuếch hoặc làm tổn hại niềm tin.","advice":"Chọn phẩm giá thay vì thắng thua và rời xa những cách làm có cái giá quá đắt.","yesNoMeaning":"Năm Kiếm nghiêng về không: chọn phẩm giá thay vì thắng thua và rời xa những cách làm có cái giá quá đắt."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-swords', 'vi', '{"name":"Sáu Kiếm","meaning":"Một chặng đường khó khăn đang dần dẫn tới điều kiện bình yên hơn.","advice":"Mang theo bài học, đón nhận hỗ trợ và tiếp tục rời xa hỗn loạn.","yesNoMeaning":"Sáu Kiếm nghiêng về có: mang theo bài học, đón nhận hỗ trợ và tiếp tục rời xa hỗn loạn."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-swords', 'vi', '{"name":"Bảy Kiếm","meaning":"Chiến lược, bí mật hoặc né tránh khiến con đường phức tạp hơn.","advice":"Hành động khéo léo nhưng minh bạch. Lối tắt phản bội niềm tin sẽ trở lại thành rắc rối.","yesNoMeaning":"Bảy Kiếm nghiêng về không: hành động khéo léo nhưng minh bạch. Lối tắt phản bội niềm tin sẽ trở lại thành rắc rối."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-swords', 'vi', '{"name":"Tám Kiếm","meaning":"Nỗi sợ và niềm tin giới hạn khiến bạn khó nhìn thấy những lựa chọn sẵn có.","advice":"Chất vấn suy nghĩ rằng mình bị mắc kẹt và thực hiện một hành động nhỏ để tự giải phóng.","yesNoMeaning":"Tám Kiếm nghiêng về không: chất vấn suy nghĩ rằng mình bị mắc kẹt và thực hiện một hành động nhỏ để tự giải phóng."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-swords', 'vi', '{"name":"Chín Kiếm","meaning":"Lo âu phóng đại nguy cơ trong bóng tối và làm tâm trí kiệt sức.","advice":"Đưa nỗi sợ ra ánh sáng, tìm hỗ trợ và phân biệt sự thật với kết quả do mình tưởng tượng.","yesNoMeaning":"Chín Kiếm nghiêng về không: đưa nỗi sợ ra ánh sáng, tìm hỗ trợ và phân biệt sự thật với kết quả do mình tưởng tượng."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-swords', 'vi', '{"name":"Mười Kiếm","meaning":"Một chu kỳ đau đớn chạm giới hạn cuối cùng và không thể tiếp tục như cũ.","advice":"Chấp nhận kết thúc, bảo vệ quá trình hồi phục và để một khởi đầu khác xuất hiện.","yesNoMeaning":"Mười Kiếm nghiêng về không: chấp nhận kết thúc, bảo vệ quá trình hồi phục và để một khởi đầu khác xuất hiện."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-swords', 'vi', '{"name":"Tiểu Đồng Kiếm","meaning":"Sự tò mò tỉnh táo tìm kiếm dữ kiện, đặt câu hỏi và theo dõi thay đổi.","advice":"Nghiên cứu cẩn thận và nói chính xác thay vì phản ứng với mọi tín hiệu.","yesNoMeaning":"Tiểu Đồng Kiếm còn tùy điều kiện: nghiên cứu cẩn thận và nói chính xác thay vì phản ứng với mọi tín hiệu."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-swords', 'vi', '{"name":"Kỵ Sĩ Kiếm","meaning":"Trí tuệ tập trung chuyển động nhanh và đối diện trực tiếp với trở ngại.","advice":"Can đảm tiến lên, nhưng đủ chậm để nghe điều mà sự chắc chắn của bạn có thể bỏ sót.","yesNoMeaning":"Kỵ Sĩ Kiếm còn tùy điều kiện: can đảm tiến lên, nhưng đủ chậm để nghe điều mà sự chắc chắn của bạn có thể bỏ sót."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-swords', 'vi', '{"name":"Nữ Hoàng Kiếm","meaning":"Nhận thức rõ ràng và ranh giới chân thành cắt bỏ sự bối rối.","advice":"Nói sự thật với lòng trắc ẩn và để kinh nghiệm làm bạn sắc sảo, không chai sạn.","yesNoMeaning":"Nữ Hoàng Kiếm nghiêng về có: nói sự thật với lòng trắc ẩn và để kinh nghiệm làm bạn sắc sảo, không chai sạn."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-swords', 'vi', '{"name":"Vua Kiếm","meaning":"Lý trí, công bằng và phán đoán có kỷ luật dẫn dắt một quyết định quan trọng.","advice":"Dựa vào bằng chứng, xác định tiêu chuẩn và gạt thiên kiến cá nhân khỏi phán đoán.","yesNoMeaning":"Vua Kiếm nghiêng về có: dựa vào bằng chứng, xác định tiêu chuẩn và gạt thiên kiến cá nhân khỏi phán đoán."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-pentacles', 'vi', '{"name":"Át Tiền","meaning":"Một cơ hội cụ thể gieo hạt cho sự đủ đầy, công việc hoặc sức khỏe tinh thần và thể chất.","advice":"Đặt cơ hội vào kế hoạch thực tế và chăm sóc nó đều đặn.","yesNoMeaning":"Át Tiền nghiêng về có: đặt cơ hội vào kế hoạch thực tế và chăm sóc nó đều đặn."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-pentacles', 'vi', '{"name":"Hai Tiền","meaning":"Nhiều ưu tiên chuyển động cùng lúc và đòi hỏi sự cân bằng linh hoạt.","advice":"Điều chỉnh nhịp độ, giữ điều thiết yếu và đừng hứa quá khả năng gánh vác.","yesNoMeaning":"Hai Tiền còn tùy điều kiện: điều chỉnh nhịp độ, giữ điều thiết yếu và đừng hứa quá khả năng gánh vác."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-pentacles', 'vi', '{"name":"Ba Tiền","meaning":"Kỹ năng phát triển qua hợp tác, phản hồi và sự trau chuốt cẩn thận.","advice":"Đóng góp thế mạnh, tôn trọng chuyên môn và cùng xây dựng theo tiêu chuẩn chung.","yesNoMeaning":"Ba Tiền nghiêng về có: đóng góp thế mạnh, tôn trọng chuyên môn và cùng xây dựng theo tiêu chuẩn chung."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-pentacles', 'vi', '{"name":"Bốn Tiền","meaning":"Bám chặt vào sự an toàn có thể giữ nguồn lực nhưng hạn chế dòng chảy lành mạnh.","advice":"Bảo vệ điều quan trọng mà không để nỗi sợ quyết định mọi thứ thay bạn.","yesNoMeaning":"Bốn Tiền còn tùy điều kiện: bảo vệ điều quan trọng mà không để nỗi sợ quyết định mọi thứ thay bạn."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-pentacles', 'vi', '{"name":"Năm Tiền","meaning":"Khó khăn vật chất hoặc cảm giác bị gạt ra ngoài gây lo lắng và thiếu thốn.","advice":"Tìm sự giúp đỡ thiết thực và chú ý cánh cửa mà nghịch cảnh khiến bạn dễ bỏ qua.","yesNoMeaning":"Năm Tiền nghiêng về không: tìm sự giúp đỡ thiết thực và chú ý cánh cửa mà nghịch cảnh khiến bạn dễ bỏ qua."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-pentacles', 'vi', '{"name":"Sáu Tiền","meaning":"Sự trao đổi nguồn lực đặt ra câu hỏi về rộng lượng, quyền lực và công bằng.","advice":"Cho hoặc nhận với thỏa thuận rõ ràng để sự hỗ trợ giữ được phẩm giá của cả hai bên.","yesNoMeaning":"Sáu Tiền nghiêng về có: cho hoặc nhận với thỏa thuận rõ ràng để sự hỗ trợ giữ được phẩm giá của cả hai bên."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-pentacles', 'vi', '{"name":"Bảy Tiền","meaning":"Đầu tư kiên nhẫn đến lúc cần đánh giá trước đợt nỗ lực tiếp theo.","advice":"Xem điều gì đang phát triển, cải thiện cách làm và cho kết quả xứng đáng đủ thời gian.","yesNoMeaning":"Bảy Tiền còn tùy điều kiện: xem điều gì đang phát triển, cải thiện cách làm và cho kết quả xứng đáng đủ thời gian."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-pentacles', 'vi', '{"name":"Tám Tiền","meaning":"Luyện tập tập trung và lặp lại tạo nên sự thành thạo cùng kết quả đáng tin.","advice":"Rèn kỹ năng cốt lõi, đón nhận sửa sai và để chất lượng tích lũy dần.","yesNoMeaning":"Tám Tiền nghiêng về có: rèn kỹ năng cốt lõi, đón nhận sửa sai và để chất lượng tích lũy dần."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-pentacles', 'vi', '{"name":"Chín Tiền","meaning":"Tự chủ và sự thoải mái được vun đắp phản ánh tiến bộ có kỷ luật.","advice":"Tận hưởng điều đã xây dựng và giữ sự độc lập gắn với lòng biết ơn.","yesNoMeaning":"Chín Tiền nghiêng về có: tận hưởng điều đã xây dựng và giữ sự độc lập gắn với lòng biết ơn."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-pentacles', 'vi', '{"name":"Mười Tiền","meaning":"An toàn lâu dài phát triển từ di sản, gia đình và nền tảng chung.","advice":"Lập kế hoạch vượt khỏi thắng lợi trước mắt và bảo vệ điều có thể nâng đỡ người khác lâu dài.","yesNoMeaning":"Mười Tiền nghiêng về có: lập kế hoạch vượt khỏi thắng lợi trước mắt và bảo vệ điều có thể nâng đỡ người khác lâu dài."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-pentacles', 'vi', '{"name":"Tiểu Đồng Tiền","meaning":"Một thông điệp thiết thực mời bạn học hỏi, lập kế hoạch hoặc bắt đầu dự án vững vàng.","advice":"Học nền tảng, xác định việc tiếp theo và kiểm chứng ý tưởng bằng công việc bền bỉ.","yesNoMeaning":"Tiểu Đồng Tiền nghiêng về có: học nền tảng, xác định việc tiếp theo và kiểm chứng ý tưởng bằng công việc bền bỉ."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-pentacles', 'vi', '{"name":"Kỵ Sĩ Tiền","meaning":"Nỗ lực đáng tin tiến chậm nhưng hiếm khi bỏ dở nhiệm vụ.","advice":"Giữ thói quen chân chính và nhất quán. Tiến bộ quan trọng hơn cảm giác hào hứng.","yesNoMeaning":"Kỵ Sĩ Tiền nghiêng về có: giữ thói quen chân chính và nhất quán. Tiến bộ quan trọng hơn cảm giác hào hứng."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-pentacles', 'vi', '{"name":"Nữ Hoàng Tiền","meaning":"Sự chăm sóc khéo léo tạo ra tiện nghi, sức khỏe và sự đủ đầy thiết thực.","advice":"Nuôi dưỡng con người và kế hoạch theo cách vẫn bền vững với chính bạn.","yesNoMeaning":"Nữ Hoàng Tiền nghiêng về có: nuôi dưỡng con người và kế hoạch theo cách vẫn bền vững với chính bạn."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-pentacles', 'vi', '{"name":"Vua Tiền","meaning":"Khả năng quản lý vật chất biến kinh nghiệm thành sự chăm lo ổn định và rộng lượng.","advice":"Đưa ra lựa chọn dài hạn vững chắc và sử dụng thành công một cách có trách nhiệm.","yesNoMeaning":"Vua Tiền nghiêng về có: đưa ra lựa chọn dài hạn vững chắc và sử dụng thành công một cách có trách nhiệm."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('aries', 'vi', '{"name":"Bạch Dương","dateRange":"21/3 – 19/4","rulingPlanet":"Sao Hỏa","summary":"Khởi đầu táo bạo và hành động thẳng thắn định hình Bạch Dương, biến ý định thành động lực tiến lên.","originStory":"Bạch Dương gắn với con cừu vàng đã cứu Phrixus trong thần thoại Hy Lạp. Bộ lông của nó sau này trở thành báu vật mà Jason và đoàn Argonaut tìm kiếm, lưu giữ hình ảnh cung này như biểu tượng của lòng can đảm, sự cứu giúp và bước đi dũng cảm đầu tiên.","traits":["Can đảm","Năng động","Độc lập","Thẳng thắn"],"strengths":["Chủ động","Tự tin","Bền bỉ"],"challenges":["Thiếu kiên nhẫn","Bốc đồng","Khởi đầu nhanh hơn khả năng duy trì"],"compatibleSigns":["Sư Tử","Nhân Mã","Song Tử"],"reflectionPrompt":"Chọn một khởi đầu can đảm và dành đủ kiên nhẫn để nó phát triển."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aries', 'day', 'vi', '{"overview":"Hôm nay thuận lợi cho một bước đi rõ ràng và có chủ đích. Bạch Dương mang năng lượng Lửa. Khởi đầu táo bạo và hành động thẳng thắn định hình Bạch Dương, biến ý định thành động lực tiến lên.","love":"Trong tình cảm hôm nay, hãy hiện diện thay vì suy đoán. Thế mạnh chủ động, tự tin, bền bỉ giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Trong công việc, hoàn thành việc ý nghĩa nhất trước khi tìm động lực mới. Dùng can đảm, năng động, độc lập, thẳng thắn làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Giữ lựa chọn tiền bạc hôm nay đơn giản và thực tế. Nhận ra khi thiếu kiên nhẫn, bốc đồng, khởi đầu nhanh hơn khả năng duy trì bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Một khoảng dừng nhỏ có thể giúp bạn lấy lại năng lượng. Chọn một khởi đầu can đảm và dành đủ kiên nhẫn để nó phát triển.","guidance":"Trước khi ngày kết thúc, hãy nhớ: Chọn một khởi đầu can đảm và dành đủ kiên nhẫn để nó phát triển."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aries', 'week', 'vi', '{"overview":"Tuần này phát triển qua lựa chọn đều đặn thay vì một khoảnh khắc kịch tính. Bạch Dương mang năng lượng Lửa. Khởi đầu táo bạo và hành động thẳng thắn định hình Bạch Dương, biến ý định thành động lực tiến lên.","love":"Các mối quan hệ được nuôi dưỡng bởi cuộc trò chuyện có cả chân thành và ấm áp. Thế mạnh chủ động, tự tin, bền bỉ giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Tiến bộ nghề nghiệp tốt nhất đến từ việc chọn một ưu tiên và bảo vệ thời gian dành cho nó. Dùng can đảm, năng động, độc lập, thẳng thắn làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Xem lại thói quen phía sau chi tiêu trước khi đưa ra cam kết lớn hơn. Nhận ra khi thiếu kiên nhẫn, bốc đồng, khởi đầu nhanh hơn khả năng duy trì bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Cân bằng vận động với hồi phục thật sự trong suốt tuần. Chọn một khởi đầu can đảm và dành đủ kiên nhẫn để nó phát triển.","guidance":"Để câu hỏi này dẫn dắt tuần của bạn: Chọn một khởi đầu can đảm và dành đủ kiên nhẫn để nó phát triển."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aries', 'year', 'vi', '{"overview":"Năm nay mời bạn kiên nhẫn phát triển bản sắc, mục đích và cách sử dụng năng lượng. Bạch Dương mang năng lượng Lửa. Khởi đầu táo bạo và hành động thẳng thắn định hình Bạch Dương, biến ý định thành động lực tiến lên.","love":"Tình yêu sâu sắc hơn khi bạn nhất quán và cho kết nối phát triển theo nhịp tự nhiên. Thế mạnh chủ động, tự tin, bền bỉ giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Công việc dài hạn vững vàng hơn khi hoài bão đi cùng cấu trúc bạn có thể duy trì. Dùng can đảm, năng động, độc lập, thẳng thắn làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Xây dựng sự tự tin tài chính bằng thói quen lặp lại được thay vì dự đoán hoàn hảo. Nhận ra khi thiếu kiên nhẫn, bốc đồng, khởi đầu nhanh hơn khả năng duy trì bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Xem sức khỏe tinh thần và thể chất là nền tảng cuộc sống đang xây dựng, không phải phần thưởng sau khi hoàn thành. Chọn một khởi đầu can đảm và dành đủ kiên nhẫn để nó phát triển.","guidance":"Trở lại định hướng này trong suốt năm: Chọn một khởi đầu can đảm và dành đủ kiên nhẫn để nó phát triển."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('taurus', 'vi', '{"name":"Kim Ngưu","dateRange":"20/4 – 20/5","rulingPlanet":"Sao Kim","summary":"Vững vàng, giàu cảm nhận và thực tế, Kim Ngưu xây dựng giá trị lâu bền bằng sự kiên nhẫn và quan tâm.","originStory":"Kim Ngưu gợi nhắc Zeus hóa thành con bò trắng tuyệt đẹp để đưa Europa vượt biển. Hình ảnh này gắn với vẻ đẹp, sự sinh sôi, đủ đầy nơi trần thế và sức mạnh được thể hiện qua sự kiên trì điềm tĩnh.","traits":["Thực tế","Trung thành","Kiên nhẫn","Giàu cảm nhận"],"strengths":["Đáng tin","Khôn ngoan thực tế","Tận tâm"],"challenges":["Cứng đầu","Ngại thay đổi","Níu giữ quá lâu"],"compatibleSigns":["Xử Nữ","Ma Kết","Cự Giải"],"reflectionPrompt":"Bảo vệ điều quan trọng mà không nhầm sự thoải mái với tính vĩnh viễn."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('taurus', 'day', 'vi', '{"overview":"Hôm nay thuận lợi cho một bước đi rõ ràng và có chủ đích. Kim Ngưu mang năng lượng Đất. Vững vàng, giàu cảm nhận và thực tế, Kim Ngưu xây dựng giá trị lâu bền bằng sự kiên nhẫn và quan tâm.","love":"Trong tình cảm hôm nay, hãy hiện diện thay vì suy đoán. Thế mạnh đáng tin, khôn ngoan thực tế, tận tâm giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Trong công việc, hoàn thành việc ý nghĩa nhất trước khi tìm động lực mới. Dùng thực tế, trung thành, kiên nhẫn, giàu cảm nhận làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Giữ lựa chọn tiền bạc hôm nay đơn giản và thực tế. Nhận ra khi cứng đầu, ngại thay đổi, níu giữ quá lâu bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Một khoảng dừng nhỏ có thể giúp bạn lấy lại năng lượng. Bảo vệ điều quan trọng mà không nhầm sự thoải mái với tính vĩnh viễn.","guidance":"Trước khi ngày kết thúc, hãy nhớ: Bảo vệ điều quan trọng mà không nhầm sự thoải mái với tính vĩnh viễn."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('taurus', 'week', 'vi', '{"overview":"Tuần này phát triển qua lựa chọn đều đặn thay vì một khoảnh khắc kịch tính. Kim Ngưu mang năng lượng Đất. Vững vàng, giàu cảm nhận và thực tế, Kim Ngưu xây dựng giá trị lâu bền bằng sự kiên nhẫn và quan tâm.","love":"Các mối quan hệ được nuôi dưỡng bởi cuộc trò chuyện có cả chân thành và ấm áp. Thế mạnh đáng tin, khôn ngoan thực tế, tận tâm giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Tiến bộ nghề nghiệp tốt nhất đến từ việc chọn một ưu tiên và bảo vệ thời gian dành cho nó. Dùng thực tế, trung thành, kiên nhẫn, giàu cảm nhận làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Xem lại thói quen phía sau chi tiêu trước khi đưa ra cam kết lớn hơn. Nhận ra khi cứng đầu, ngại thay đổi, níu giữ quá lâu bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Cân bằng vận động với hồi phục thật sự trong suốt tuần. Bảo vệ điều quan trọng mà không nhầm sự thoải mái với tính vĩnh viễn.","guidance":"Để câu hỏi này dẫn dắt tuần của bạn: Bảo vệ điều quan trọng mà không nhầm sự thoải mái với tính vĩnh viễn."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('taurus', 'year', 'vi', '{"overview":"Năm nay mời bạn kiên nhẫn phát triển bản sắc, mục đích và cách sử dụng năng lượng. Kim Ngưu mang năng lượng Đất. Vững vàng, giàu cảm nhận và thực tế, Kim Ngưu xây dựng giá trị lâu bền bằng sự kiên nhẫn và quan tâm.","love":"Tình yêu sâu sắc hơn khi bạn nhất quán và cho kết nối phát triển theo nhịp tự nhiên. Thế mạnh đáng tin, khôn ngoan thực tế, tận tâm giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Công việc dài hạn vững vàng hơn khi hoài bão đi cùng cấu trúc bạn có thể duy trì. Dùng thực tế, trung thành, kiên nhẫn, giàu cảm nhận làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Xây dựng sự tự tin tài chính bằng thói quen lặp lại được thay vì dự đoán hoàn hảo. Nhận ra khi cứng đầu, ngại thay đổi, níu giữ quá lâu bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Xem sức khỏe tinh thần và thể chất là nền tảng cuộc sống đang xây dựng, không phải phần thưởng sau khi hoàn thành. Bảo vệ điều quan trọng mà không nhầm sự thoải mái với tính vĩnh viễn.","guidance":"Trở lại định hướng này trong suốt năm: Bảo vệ điều quan trọng mà không nhầm sự thoải mái với tính vĩnh viễn."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('gemini', 'vi', '{"name":"Song Tử","dateRange":"21/5 – 20/6","rulingPlanet":"Sao Thủy","summary":"Sự tò mò và kết nối dẫn dắt Song Tử thu thập ý tưởng và nhận ra nhiều mặt của một câu chuyện.","originStory":"Song Tử đại diện cho Castor và Pollux, cặp song sinh gắn bó chọn chia sẻ sự bất tử thay vì xa nhau. Chòm sao của họ mang chủ đề đồng hành, góc nhìn hai chiều, giao tiếp và sự chuyển động giữa các thế giới.","traits":["Tò mò","Linh hoạt","Giàu biểu đạt","Nhanh trí"],"strengths":["Giao tiếp","Đa năng","Học hỏi nhanh"],"challenges":["Bồn chồn","Phân tán chú ý","Suy nghĩ quá nhiều"],"compatibleSigns":["Thiên Bình","Bảo Bình","Bạch Dương"],"reflectionPrompt":"Để sự tò mò mở cửa, rồi ở lại đủ lâu để hiểu điều bạn tìm thấy."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('gemini', 'day', 'vi', '{"overview":"Hôm nay thuận lợi cho một bước đi rõ ràng và có chủ đích. Song Tử mang năng lượng Khí. Sự tò mò và kết nối dẫn dắt Song Tử thu thập ý tưởng và nhận ra nhiều mặt của một câu chuyện.","love":"Trong tình cảm hôm nay, hãy hiện diện thay vì suy đoán. Thế mạnh giao tiếp, đa năng, học hỏi nhanh giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Trong công việc, hoàn thành việc ý nghĩa nhất trước khi tìm động lực mới. Dùng tò mò, linh hoạt, giàu biểu đạt, nhanh trí làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Giữ lựa chọn tiền bạc hôm nay đơn giản và thực tế. Nhận ra khi bồn chồn, phân tán chú ý, suy nghĩ quá nhiều bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Một khoảng dừng nhỏ có thể giúp bạn lấy lại năng lượng. Để sự tò mò mở cửa, rồi ở lại đủ lâu để hiểu điều bạn tìm thấy.","guidance":"Trước khi ngày kết thúc, hãy nhớ: Để sự tò mò mở cửa, rồi ở lại đủ lâu để hiểu điều bạn tìm thấy."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('gemini', 'week', 'vi', '{"overview":"Tuần này phát triển qua lựa chọn đều đặn thay vì một khoảnh khắc kịch tính. Song Tử mang năng lượng Khí. Sự tò mò và kết nối dẫn dắt Song Tử thu thập ý tưởng và nhận ra nhiều mặt của một câu chuyện.","love":"Các mối quan hệ được nuôi dưỡng bởi cuộc trò chuyện có cả chân thành và ấm áp. Thế mạnh giao tiếp, đa năng, học hỏi nhanh giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Tiến bộ nghề nghiệp tốt nhất đến từ việc chọn một ưu tiên và bảo vệ thời gian dành cho nó. Dùng tò mò, linh hoạt, giàu biểu đạt, nhanh trí làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Xem lại thói quen phía sau chi tiêu trước khi đưa ra cam kết lớn hơn. Nhận ra khi bồn chồn, phân tán chú ý, suy nghĩ quá nhiều bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Cân bằng vận động với hồi phục thật sự trong suốt tuần. Để sự tò mò mở cửa, rồi ở lại đủ lâu để hiểu điều bạn tìm thấy.","guidance":"Để câu hỏi này dẫn dắt tuần của bạn: Để sự tò mò mở cửa, rồi ở lại đủ lâu để hiểu điều bạn tìm thấy."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('gemini', 'year', 'vi', '{"overview":"Năm nay mời bạn kiên nhẫn phát triển bản sắc, mục đích và cách sử dụng năng lượng. Song Tử mang năng lượng Khí. Sự tò mò và kết nối dẫn dắt Song Tử thu thập ý tưởng và nhận ra nhiều mặt của một câu chuyện.","love":"Tình yêu sâu sắc hơn khi bạn nhất quán và cho kết nối phát triển theo nhịp tự nhiên. Thế mạnh giao tiếp, đa năng, học hỏi nhanh giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Công việc dài hạn vững vàng hơn khi hoài bão đi cùng cấu trúc bạn có thể duy trì. Dùng tò mò, linh hoạt, giàu biểu đạt, nhanh trí làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Xây dựng sự tự tin tài chính bằng thói quen lặp lại được thay vì dự đoán hoàn hảo. Nhận ra khi bồn chồn, phân tán chú ý, suy nghĩ quá nhiều bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Xem sức khỏe tinh thần và thể chất là nền tảng cuộc sống đang xây dựng, không phải phần thưởng sau khi hoàn thành. Để sự tò mò mở cửa, rồi ở lại đủ lâu để hiểu điều bạn tìm thấy.","guidance":"Trở lại định hướng này trong suốt năm: Để sự tò mò mở cửa, rồi ở lại đủ lâu để hiểu điều bạn tìm thấy."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('cancer', 'vi', '{"name":"Cự Giải","dateRange":"21/6 – 22/7","rulingPlanet":"Mặt Trăng","summary":"Giàu trực giác và tinh thần che chở, Cự Giải tạo cảm giác thuộc về bằng cách trân trọng ký ức, cảm xúc và mái ấm.","originStory":"Cự Giải gắn với cua Karkinos, được đưa lên bầu trời sau khi thể hiện lòng trung thành trong trận chiến giữa Heracles và Hydra. Mai cua cùng sự chủ quản của Mặt Trăng tượng trưng cho che chở, những đợt thủy triều cảm xúc và sự tận tâm với người thân cận.","traits":["Trực giác tốt","Chu đáo","Biết che chở","Giàu tưởng tượng"],"strengths":["Đồng cảm","Trung thành","Thấu hiểu cảm xúc"],"challenges":["Tâm trạng thất thường","Thu mình sau lớp phòng vệ","Dễ chạnh lòng"],"compatibleSigns":["Bọ Cạp","Song Ngư","Kim Ngưu"],"reflectionPrompt":"Chăm sóc thế giới bên trong, đồng thời mở cửa cho sự kết nối chân thành."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('cancer', 'day', 'vi', '{"overview":"Hôm nay thuận lợi cho một bước đi rõ ràng và có chủ đích. Cự Giải mang năng lượng Nước. Giàu trực giác và tinh thần che chở, Cự Giải tạo cảm giác thuộc về bằng cách trân trọng ký ức, cảm xúc và mái ấm.","love":"Trong tình cảm hôm nay, hãy hiện diện thay vì suy đoán. Thế mạnh đồng cảm, trung thành, thấu hiểu cảm xúc giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Trong công việc, hoàn thành việc ý nghĩa nhất trước khi tìm động lực mới. Dùng trực giác tốt, chu đáo, biết che chở, giàu tưởng tượng làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Giữ lựa chọn tiền bạc hôm nay đơn giản và thực tế. Nhận ra khi tâm trạng thất thường, thu mình sau lớp phòng vệ, dễ chạnh lòng bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Một khoảng dừng nhỏ có thể giúp bạn lấy lại năng lượng. Chăm sóc thế giới bên trong, đồng thời mở cửa cho sự kết nối chân thành.","guidance":"Trước khi ngày kết thúc, hãy nhớ: Chăm sóc thế giới bên trong, đồng thời mở cửa cho sự kết nối chân thành."}');
