INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('leo', 'vi', '{"name":"Sư Tử","dateRange":"23/7 – 22/8","rulingPlanet":"Mặt Trời","summary":"Sự ấm áp, sáng tạo và biểu đạt hào phóng khiến Sư Tử trở thành nguồn ánh sáng tự nhiên.","originStory":"Sư Tử gắn với sư tử Nemea, sinh vật gần như bất khả xâm phạm bị đánh bại trong chiến công đầu tiên của Heracles. Được đưa lên bầu trời, nó trở thành biểu tượng của can đảm, phong thái uy nghi và sức sáng tạo của Mặt Trời.","traits":["Ấm áp","Sáng tạo","Rộng lượng","Tự tin"],"strengths":["Lãnh đạo","Trung thành","Biểu đạt chân thành"],"challenges":["Kiêu hãnh","Cần được ghi nhận","Phóng đại trở ngại"],"compatibleSigns":["Bạch Dương","Nhân Mã","Thiên Bình"],"reflectionPrompt":"Rộng lượng chia sẻ ánh sáng và để người khác tỏa sáng bên bạn."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('leo', 'day', 'vi', '{"overview":"Hôm nay thuận lợi cho một bước đi rõ ràng và có chủ đích. Sư Tử mang năng lượng Lửa. Sự ấm áp, sáng tạo và biểu đạt hào phóng khiến Sư Tử trở thành nguồn ánh sáng tự nhiên.","love":"Trong tình cảm hôm nay, hãy hiện diện thay vì suy đoán. Thế mạnh lãnh đạo, trung thành, biểu đạt chân thành giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Trong công việc, hoàn thành việc ý nghĩa nhất trước khi tìm động lực mới. Dùng ấm áp, sáng tạo, rộng lượng, tự tin làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Giữ lựa chọn tiền bạc hôm nay đơn giản và thực tế. Nhận ra khi kiêu hãnh, cần được ghi nhận, phóng đại trở ngại bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Một khoảng dừng nhỏ có thể giúp bạn lấy lại năng lượng. Rộng lượng chia sẻ ánh sáng và để người khác tỏa sáng bên bạn.","guidance":"Trước khi ngày kết thúc, hãy nhớ: Rộng lượng chia sẻ ánh sáng và để người khác tỏa sáng bên bạn."}');
