INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('leo', 'year', 'vi', '{"overview":"Năm nay mời bạn kiên nhẫn phát triển bản sắc, mục đích và cách sử dụng năng lượng. Sư Tử mang năng lượng Lửa. Sự ấm áp, sáng tạo và biểu đạt hào phóng khiến Sư Tử trở thành nguồn ánh sáng tự nhiên.","love":"Tình yêu sâu sắc hơn khi bạn nhất quán và cho kết nối phát triển theo nhịp tự nhiên. Thế mạnh lãnh đạo, trung thành, biểu đạt chân thành giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Công việc dài hạn vững vàng hơn khi hoài bão đi cùng cấu trúc bạn có thể duy trì. Dùng ấm áp, sáng tạo, rộng lượng, tự tin làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Xây dựng sự tự tin tài chính bằng thói quen lặp lại được thay vì dự đoán hoàn hảo. Nhận ra khi kiêu hãnh, cần được ghi nhận, phóng đại trở ngại bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Xem sức khỏe tinh thần và thể chất là nền tảng cuộc sống đang xây dựng, không phải phần thưởng sau khi hoàn thành. Rộng lượng chia sẻ ánh sáng và để người khác tỏa sáng bên bạn.","guidance":"Trở lại định hướng này trong suốt năm: Rộng lượng chia sẻ ánh sáng và để người khác tỏa sáng bên bạn."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('virgo', 'vi', '{"name":"Xử Nữ","dateRange":"23/8 – 22/9","rulingPlanet":"Sao Thủy","summary":"Khả năng phân định và tinh thần phụng sự dẫn dắt Xử Nữ biến quan sát cẩn thận thành cải thiện thiết thực.","originStory":"Xử Nữ thường gắn với Astraea, thiếu nữ công lý ở lại với loài người sau khi các vị thần khác rời đi. Bông lúa nàng mang liên hệ cung này với mùa gặt, kỹ năng, ý định trong sáng và việc chăm nom những gì duy trì sự sống.","traits":["Tinh ý","Thực tế","Chu đáo","Chính xác"],"strengths":["Phân tích","Tay nghề","Hỗ trợ hữu ích"],"challenges":["Cầu toàn","Tự phê bình","Lo lắng về tiểu tiết"],"compatibleSigns":["Kim Ngưu","Ma Kết","Cự Giải"],"reflectionPrompt":"Cải thiện điều có thể và cho phép công việc tốt được hoàn thành trước khi hoàn hảo."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('virgo', 'day', 'vi', '{"overview":"Hôm nay thuận lợi cho một bước đi rõ ràng và có chủ đích. Xử Nữ mang năng lượng Đất. Khả năng phân định và tinh thần phụng sự dẫn dắt Xử Nữ biến quan sát cẩn thận thành cải thiện thiết thực.","love":"Trong tình cảm hôm nay, hãy hiện diện thay vì suy đoán. Thế mạnh phân tích, tay nghề, hỗ trợ hữu ích giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Trong công việc, hoàn thành việc ý nghĩa nhất trước khi tìm động lực mới. Dùng tinh ý, thực tế, chu đáo, chính xác làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Giữ lựa chọn tiền bạc hôm nay đơn giản và thực tế. Nhận ra khi cầu toàn, tự phê bình, lo lắng về tiểu tiết bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Một khoảng dừng nhỏ có thể giúp bạn lấy lại năng lượng. Cải thiện điều có thể và cho phép công việc tốt được hoàn thành trước khi hoàn hảo.","guidance":"Trước khi ngày kết thúc, hãy nhớ: Cải thiện điều có thể và cho phép công việc tốt được hoàn thành trước khi hoàn hảo."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('virgo', 'week', 'vi', '{"overview":"Tuần này phát triển qua lựa chọn đều đặn thay vì một khoảnh khắc kịch tính. Xử Nữ mang năng lượng Đất. Khả năng phân định và tinh thần phụng sự dẫn dắt Xử Nữ biến quan sát cẩn thận thành cải thiện thiết thực.","love":"Các mối quan hệ được nuôi dưỡng bởi cuộc trò chuyện có cả chân thành và ấm áp. Thế mạnh phân tích, tay nghề, hỗ trợ hữu ích giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Tiến bộ nghề nghiệp tốt nhất đến từ việc chọn một ưu tiên và bảo vệ thời gian dành cho nó. Dùng tinh ý, thực tế, chu đáo, chính xác làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Xem lại thói quen phía sau chi tiêu trước khi đưa ra cam kết lớn hơn. Nhận ra khi cầu toàn, tự phê bình, lo lắng về tiểu tiết bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Cân bằng vận động với hồi phục thật sự trong suốt tuần. Cải thiện điều có thể và cho phép công việc tốt được hoàn thành trước khi hoàn hảo.","guidance":"Để câu hỏi này dẫn dắt tuần của bạn: Cải thiện điều có thể và cho phép công việc tốt được hoàn thành trước khi hoàn hảo."}');
