INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('libra', 'vi', '{"name":"Thiên Bình","dateRange":"23/9 – 22/10","rulingPlanet":"Sao Kim","summary":"Cân bằng, vẻ đẹp và sự có đi có lại dẫn Thiên Bình tới lựa chọn tôn trọng mọi tiếng nói.","originStory":"Cán cân của Thiên Bình được nữ thần công lý Astraea cầm trên tay, là biểu tượng vô tri duy nhất trong vòng Hoàng đạo. Nó đại diện cho phán đoán có cân nhắc, hòa hợp xã hội và nỗ lực liên tục khôi phục cân bằng thay vì mặc định cân bằng đã có sẵn.","traits":["Ngoại giao","Công tâm","Duyên dáng","Hợp tác"],"strengths":["Hòa giải","Đa chiều","Tạo hòa hợp"],"challenges":["Do dự","Chiều lòng người khác","Né tránh xung đột cần thiết"],"compatibleSigns":["Song Tử","Bảo Bình","Sư Tử"],"reflectionPrompt":"Tìm kiếm công bằng mà không bỏ quên nhu cầu thật sự của mình."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('libra', 'day', 'vi', '{"overview":"Hôm nay thuận lợi cho một bước đi rõ ràng và có chủ đích. Thiên Bình mang năng lượng Khí. Cân bằng, vẻ đẹp và sự có đi có lại dẫn Thiên Bình tới lựa chọn tôn trọng mọi tiếng nói.","love":"Trong tình cảm hôm nay, hãy hiện diện thay vì suy đoán. Thế mạnh hòa giải, đa chiều, tạo hòa hợp giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Trong công việc, hoàn thành việc ý nghĩa nhất trước khi tìm động lực mới. Dùng ngoại giao, công tâm, duyên dáng, hợp tác làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Giữ lựa chọn tiền bạc hôm nay đơn giản và thực tế. Nhận ra khi do dự, chiều lòng người khác, né tránh xung đột cần thiết bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Một khoảng dừng nhỏ có thể giúp bạn lấy lại năng lượng. Tìm kiếm công bằng mà không bỏ quên nhu cầu thật sự của mình.","guidance":"Trước khi ngày kết thúc, hãy nhớ: Tìm kiếm công bằng mà không bỏ quên nhu cầu thật sự của mình."}');
