INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('scorpio', 'vi', '{"name":"Bọ Cạp","dateRange":"23/10 – 21/11","rulingPlanet":"Sao Diêm Vương","summary":"Chiều sâu và sự chuyển hóa định hình Bọ Cạp, với khả năng tìm sự thật bên dưới bề mặt.","originStory":"Bọ Cạp gợi nhắc con bọ cạp được gửi đến đối đầu thợ săn Orion sau khi lòng kiêu hãnh của chàng làm đảo lộn trật tự tự nhiên. Vị trí đối nhau trên bầu trời gợi về ranh giới, hệ quả, điều bí ẩn và sức tái sinh sau một kết thúc.","traits":["Mãnh liệt","Sâu sắc","Trung thành","Tháo vát"],"strengths":["Can đảm với cảm xúc","Tập trung","Chuyển hóa"],"challenges":["Giữ kín","Nghi ngờ","Giữ lòng oán giận"],"compatibleSigns":["Cự Giải","Song Ngư","Xử Nữ"],"reflectionPrompt":"Dùng chiều sâu để chuyển hóa sự thật, không phải để che giấu nó."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('scorpio', 'day', 'vi', '{"overview":"Hôm nay thuận lợi cho một bước đi rõ ràng và có chủ đích. Bọ Cạp mang năng lượng Nước. Chiều sâu và sự chuyển hóa định hình Bọ Cạp, với khả năng tìm sự thật bên dưới bề mặt.","love":"Trong tình cảm hôm nay, hãy hiện diện thay vì suy đoán. Thế mạnh can đảm với cảm xúc, tập trung, chuyển hóa giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Trong công việc, hoàn thành việc ý nghĩa nhất trước khi tìm động lực mới. Dùng mãnh liệt, sâu sắc, trung thành, tháo vát làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Giữ lựa chọn tiền bạc hôm nay đơn giản và thực tế. Nhận ra khi giữ kín, nghi ngờ, giữ lòng oán giận bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Một khoảng dừng nhỏ có thể giúp bạn lấy lại năng lượng. Dùng chiều sâu để chuyển hóa sự thật, không phải để che giấu nó.","guidance":"Trước khi ngày kết thúc, hãy nhớ: Dùng chiều sâu để chuyển hóa sự thật, không phải để che giấu nó."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('scorpio', 'week', 'vi', '{"overview":"Tuần này phát triển qua lựa chọn đều đặn thay vì một khoảnh khắc kịch tính. Bọ Cạp mang năng lượng Nước. Chiều sâu và sự chuyển hóa định hình Bọ Cạp, với khả năng tìm sự thật bên dưới bề mặt.","love":"Các mối quan hệ được nuôi dưỡng bởi cuộc trò chuyện có cả chân thành và ấm áp. Thế mạnh can đảm với cảm xúc, tập trung, chuyển hóa giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Tiến bộ nghề nghiệp tốt nhất đến từ việc chọn một ưu tiên và bảo vệ thời gian dành cho nó. Dùng mãnh liệt, sâu sắc, trung thành, tháo vát làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Xem lại thói quen phía sau chi tiêu trước khi đưa ra cam kết lớn hơn. Nhận ra khi giữ kín, nghi ngờ, giữ lòng oán giận bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Cân bằng vận động với hồi phục thật sự trong suốt tuần. Dùng chiều sâu để chuyển hóa sự thật, không phải để che giấu nó.","guidance":"Để câu hỏi này dẫn dắt tuần của bạn: Dùng chiều sâu để chuyển hóa sự thật, không phải để che giấu nó."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('scorpio', 'year', 'vi', '{"overview":"Năm nay mời bạn kiên nhẫn phát triển bản sắc, mục đích và cách sử dụng năng lượng. Bọ Cạp mang năng lượng Nước. Chiều sâu và sự chuyển hóa định hình Bọ Cạp, với khả năng tìm sự thật bên dưới bề mặt.","love":"Tình yêu sâu sắc hơn khi bạn nhất quán và cho kết nối phát triển theo nhịp tự nhiên. Thế mạnh can đảm với cảm xúc, tập trung, chuyển hóa giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Công việc dài hạn vững vàng hơn khi hoài bão đi cùng cấu trúc bạn có thể duy trì. Dùng mãnh liệt, sâu sắc, trung thành, tháo vát làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Xây dựng sự tự tin tài chính bằng thói quen lặp lại được thay vì dự đoán hoàn hảo. Nhận ra khi giữ kín, nghi ngờ, giữ lòng oán giận bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Xem sức khỏe tinh thần và thể chất là nền tảng cuộc sống đang xây dựng, không phải phần thưởng sau khi hoàn thành. Dùng chiều sâu để chuyển hóa sự thật, không phải để che giấu nó.","guidance":"Trở lại định hướng này trong suốt năm: Dùng chiều sâu để chuyển hóa sự thật, không phải để che giấu nó."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('sagittarius', 'vi', '{"name":"Nhân Mã","dateRange":"22/11 – 21/12","rulingPlanet":"Sao Mộc","summary":"Nhân Mã tìm chân trời rộng hơn qua sự thật, hành trình, học hỏi và tinh thần lạc quan có mục đích.","originStory":"Nhân Mã thường được liên hệ với Chiron, nhân mã thông thái và người thầy có mũi tên hướng vượt khỏi điều quen thuộc. Chòm sao tượng trưng cho sự kết hợp giữa bản năng và hiểu biết cao hơn, luôn hướng tới chân trời có ý nghĩa hơn.","traits":["Ưa khám phá","Lạc quan","Thẳng thắn","Thích triết lý"],"strengths":["Tầm nhìn","Nhiệt huyết","Cởi mở"],"challenges":["Thẳng quá mức","Hứa quá khả năng","Trốn tránh nề nếp"],"compatibleSigns":["Bạch Dương","Sư Tử","Bảo Bình"],"reflectionPrompt":"Nhắm xa, nhưng chọn hướng mà hành động hằng ngày có thể hỗ trợ."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('sagittarius', 'day', 'vi', '{"overview":"Hôm nay thuận lợi cho một bước đi rõ ràng và có chủ đích. Nhân Mã mang năng lượng Lửa. Nhân Mã tìm chân trời rộng hơn qua sự thật, hành trình, học hỏi và tinh thần lạc quan có mục đích.","love":"Trong tình cảm hôm nay, hãy hiện diện thay vì suy đoán. Thế mạnh tầm nhìn, nhiệt huyết, cởi mở giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Trong công việc, hoàn thành việc ý nghĩa nhất trước khi tìm động lực mới. Dùng ưa khám phá, lạc quan, thẳng thắn, thích triết lý làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Giữ lựa chọn tiền bạc hôm nay đơn giản và thực tế. Nhận ra khi thẳng quá mức, hứa quá khả năng, trốn tránh nề nếp bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Một khoảng dừng nhỏ có thể giúp bạn lấy lại năng lượng. Nhắm xa, nhưng chọn hướng mà hành động hằng ngày có thể hỗ trợ.","guidance":"Trước khi ngày kết thúc, hãy nhớ: Nhắm xa, nhưng chọn hướng mà hành động hằng ngày có thể hỗ trợ."}');
