INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('capricorn', 'vi', '{"name":"Ma Kết","dateRange":"22/12 – 19/1","rulingPlanet":"Sao Thổ","summary":"Kỷ luật và tầm nhìn dài hạn giúp Ma Kết vươn cao mà vẫn hiểu những chiều sâu bên dưới.","originStory":"Dê biển Ma Kết gắn với Pan, người hóa một phần cơ thể thành cá khi trốn Typhon. Bản chất núi và biển kết hợp hoài bão với khả năng sinh tồn cảm xúc, trân trọng sự thành thạo được tích lũy qua thời gian và trách nhiệm.","traits":["Tham vọng","Kỷ luật","Kiên nhẫn","Trách nhiệm"],"strengths":["Sức bền","Chiến lược","Đáng tin cậy"],"challenges":["Cứng nhắc","Bi quan","Đo giá trị bản thân bằng thành tích"],"compatibleSigns":["Kim Ngưu","Xử Nữ","Bọ Cạp"],"reflectionPrompt":"Xây dựng cho dài hạn và nhớ rằng nghỉ ngơi cũng là một phần của nền tảng."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('capricorn', 'day', 'vi', '{"overview":"Hôm nay thuận lợi cho một bước đi rõ ràng và có chủ đích. Ma Kết mang năng lượng Đất. Kỷ luật và tầm nhìn dài hạn giúp Ma Kết vươn cao mà vẫn hiểu những chiều sâu bên dưới.","love":"Trong tình cảm hôm nay, hãy hiện diện thay vì suy đoán. Thế mạnh sức bền, chiến lược, đáng tin cậy giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Trong công việc, hoàn thành việc ý nghĩa nhất trước khi tìm động lực mới. Dùng tham vọng, kỷ luật, kiên nhẫn, trách nhiệm làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Giữ lựa chọn tiền bạc hôm nay đơn giản và thực tế. Nhận ra khi cứng nhắc, bi quan, đo giá trị bản thân bằng thành tích bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Một khoảng dừng nhỏ có thể giúp bạn lấy lại năng lượng. Xây dựng cho dài hạn và nhớ rằng nghỉ ngơi cũng là một phần của nền tảng.","guidance":"Trước khi ngày kết thúc, hãy nhớ: Xây dựng cho dài hạn và nhớ rằng nghỉ ngơi cũng là một phần của nền tảng."}');
