INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('capricorn', 'year', 'vi', '{"overview":"Năm nay mời bạn kiên nhẫn phát triển bản sắc, mục đích và cách sử dụng năng lượng. Ma Kết mang năng lượng Đất. Kỷ luật và tầm nhìn dài hạn giúp Ma Kết vươn cao mà vẫn hiểu những chiều sâu bên dưới.","love":"Tình yêu sâu sắc hơn khi bạn nhất quán và cho kết nối phát triển theo nhịp tự nhiên. Thế mạnh sức bền, chiến lược, đáng tin cậy giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Công việc dài hạn vững vàng hơn khi hoài bão đi cùng cấu trúc bạn có thể duy trì. Dùng tham vọng, kỷ luật, kiên nhẫn, trách nhiệm làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Xây dựng sự tự tin tài chính bằng thói quen lặp lại được thay vì dự đoán hoàn hảo. Nhận ra khi cứng nhắc, bi quan, đo giá trị bản thân bằng thành tích bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Xem sức khỏe tinh thần và thể chất là nền tảng cuộc sống đang xây dựng, không phải phần thưởng sau khi hoàn thành. Xây dựng cho dài hạn và nhớ rằng nghỉ ngơi cũng là một phần của nền tảng.","guidance":"Trở lại định hướng này trong suốt năm: Xây dựng cho dài hạn và nhớ rằng nghỉ ngơi cũng là một phần của nền tảng."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('aquarius', 'vi', '{"name":"Bảo Bình","dateRange":"20/1 – 18/2","rulingPlanet":"Sao Thiên Vương","summary":"Tư duy độc lập và tầm nhìn cộng đồng dẫn Bảo Bình rót những ý tưởng mới vào thế giới.","originStory":"Bảo Bình gắn với Ganymede, người dâng chén mang nước đến cho các vị thần và, theo nghĩa biểu tượng, tri thức đến nhân loại. Dù hình ảnh mang nước, cung này thuộc nguyên tố Khí: ý tưởng, hệ thống và sự đổi mới được sẻ chia vì lợi ích chung.","traits":["Độc đáo","Độc lập","Nhân văn","Sáng kiến"],"strengths":["Đổi mới","Khách quan","Tầm nhìn cộng đồng"],"challenges":["Xa cách","Thói quen phản đối","Quan điểm cố định"],"compatibleSigns":["Song Tử","Thiên Bình","Nhân Mã"],"reflectionPrompt":"Để sự khác biệt phục vụ kết nối thay vì tạo khoảng cách."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aquarius', 'day', 'vi', '{"overview":"Hôm nay thuận lợi cho một bước đi rõ ràng và có chủ đích. Bảo Bình mang năng lượng Khí. Tư duy độc lập và tầm nhìn cộng đồng dẫn Bảo Bình rót những ý tưởng mới vào thế giới.","love":"Trong tình cảm hôm nay, hãy hiện diện thay vì suy đoán. Thế mạnh đổi mới, khách quan, tầm nhìn cộng đồng giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Trong công việc, hoàn thành việc ý nghĩa nhất trước khi tìm động lực mới. Dùng độc đáo, độc lập, nhân văn, sáng kiến làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Giữ lựa chọn tiền bạc hôm nay đơn giản và thực tế. Nhận ra khi xa cách, thói quen phản đối, quan điểm cố định bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Một khoảng dừng nhỏ có thể giúp bạn lấy lại năng lượng. Để sự khác biệt phục vụ kết nối thay vì tạo khoảng cách.","guidance":"Trước khi ngày kết thúc, hãy nhớ: Để sự khác biệt phục vụ kết nối thay vì tạo khoảng cách."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aquarius', 'week', 'vi', '{"overview":"Tuần này phát triển qua lựa chọn đều đặn thay vì một khoảnh khắc kịch tính. Bảo Bình mang năng lượng Khí. Tư duy độc lập và tầm nhìn cộng đồng dẫn Bảo Bình rót những ý tưởng mới vào thế giới.","love":"Các mối quan hệ được nuôi dưỡng bởi cuộc trò chuyện có cả chân thành và ấm áp. Thế mạnh đổi mới, khách quan, tầm nhìn cộng đồng giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Tiến bộ nghề nghiệp tốt nhất đến từ việc chọn một ưu tiên và bảo vệ thời gian dành cho nó. Dùng độc đáo, độc lập, nhân văn, sáng kiến làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Xem lại thói quen phía sau chi tiêu trước khi đưa ra cam kết lớn hơn. Nhận ra khi xa cách, thói quen phản đối, quan điểm cố định bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Cân bằng vận động với hồi phục thật sự trong suốt tuần. Để sự khác biệt phục vụ kết nối thay vì tạo khoảng cách.","guidance":"Để câu hỏi này dẫn dắt tuần của bạn: Để sự khác biệt phục vụ kết nối thay vì tạo khoảng cách."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aquarius', 'year', 'vi', '{"overview":"Năm nay mời bạn kiên nhẫn phát triển bản sắc, mục đích và cách sử dụng năng lượng. Bảo Bình mang năng lượng Khí. Tư duy độc lập và tầm nhìn cộng đồng dẫn Bảo Bình rót những ý tưởng mới vào thế giới.","love":"Tình yêu sâu sắc hơn khi bạn nhất quán và cho kết nối phát triển theo nhịp tự nhiên. Thế mạnh đổi mới, khách quan, tầm nhìn cộng đồng giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Công việc dài hạn vững vàng hơn khi hoài bão đi cùng cấu trúc bạn có thể duy trì. Dùng độc đáo, độc lập, nhân văn, sáng kiến làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Xây dựng sự tự tin tài chính bằng thói quen lặp lại được thay vì dự đoán hoàn hảo. Nhận ra khi xa cách, thói quen phản đối, quan điểm cố định bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Xem sức khỏe tinh thần và thể chất là nền tảng cuộc sống đang xây dựng, không phải phần thưởng sau khi hoàn thành. Để sự khác biệt phục vụ kết nối thay vì tạo khoảng cách.","guidance":"Trở lại định hướng này trong suốt năm: Để sự khác biệt phục vụ kết nối thay vì tạo khoảng cách."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('pisces', 'vi', '{"name":"Song Ngư","dateRange":"19/2 – 20/3","rulingPlanet":"Sao Hải Vương","summary":"Lòng trắc ẩn và trí tưởng tượng dẫn Song Ngư qua trực giác, giấc mơ và cảm xúc sẻ chia.","originStory":"Song Ngư gợi nhắc Aphrodite và Eros hóa thành cá, buộc mình với nhau để trốn Typhon. Sợi dây giữa hai con cá tượng trưng cho tận tụy, bản sắc linh hoạt, sự nhạy cảm tinh thần và khả năng tìm thấy thống nhất giữa những dòng chảy đổi thay.","traits":["Trắc ẩn","Giàu tưởng tượng","Trực giác tốt","Dịu dàng"],"strengths":["Đồng cảm","Sáng tạo","Thấu hiểu tinh thần"],"challenges":["Trốn tránh thực tại","Ranh giới mờ nhạt","Hấp thụ cảm xúc người khác"],"compatibleSigns":["Cự Giải","Bọ Cạp","Ma Kết"],"reflectionPrompt":"Trân trọng sự nhạy cảm bằng những ranh giới đủ vững để bảo vệ nó."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('pisces', 'day', 'vi', '{"overview":"Hôm nay thuận lợi cho một bước đi rõ ràng và có chủ đích. Song Ngư mang năng lượng Nước. Lòng trắc ẩn và trí tưởng tượng dẫn Song Ngư qua trực giác, giấc mơ và cảm xúc sẻ chia.","love":"Trong tình cảm hôm nay, hãy hiện diện thay vì suy đoán. Thế mạnh đồng cảm, sáng tạo, thấu hiểu tinh thần giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Trong công việc, hoàn thành việc ý nghĩa nhất trước khi tìm động lực mới. Dùng trắc ẩn, giàu tưởng tượng, trực giác tốt, dịu dàng làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Giữ lựa chọn tiền bạc hôm nay đơn giản và thực tế. Nhận ra khi trốn tránh thực tại, ranh giới mờ nhạt, hấp thụ cảm xúc người khác bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Một khoảng dừng nhỏ có thể giúp bạn lấy lại năng lượng. Trân trọng sự nhạy cảm bằng những ranh giới đủ vững để bảo vệ nó.","guidance":"Trước khi ngày kết thúc, hãy nhớ: Trân trọng sự nhạy cảm bằng những ranh giới đủ vững để bảo vệ nó."}');
